Object.assign(window.TEM8_DICTIONARY, {"nature":{"media":{"uk":"media/uk/nature__gb_1.mp3","us":"media/us/nature__us_1.mp3"},"oxford":{"phon":"ˈneɪtʃə(r)","pos":"noun","senses":[{"en":"all the plants, animals and things that exist in the universe that are not made by people","cn":"自然界；大自然","g":"[uncountable]","sc":"plants, animals","ex":{"en":"Take time to appreciate the beauties of nature.","cn":"悠闲地欣赏自然界中美好的东西。"}},{"en":"the way that things happen in the physical world when it is not controlled by people","cn":"自然；自然方式","g":"[uncountable]","sc":"plants, animals","ex":{"en":"The forces of nature are constantly reshaping our world.","cn":"自然界的力量在不断重塑我们的世界。"}},{"en":"the usual way that a person or an animal behaves that is part of their character","cn":"天性；本性；性格","g":"[countable, uncountable]","sc":"character","ex":{"en":"She is very sensitive by nature.","cn":"她生性很敏感。"}},{"en":"the basic qualities of a thing","cn":"基本特征；本质；基本性质","g":"[singular]","sc":"basic qualities","ex":{"en":"the changing nature of society","cn":"不断变化的社会性质"}},{"en":"a type or kind of something","cn":"种类；类型","g":"[singular]","sc":"type/kind","ex":{"en":"His books were mainly of a scientific nature.","cn":"他的书主要是科学类的。"}},{"en":"having the type of character or quality mentioned","cn":"有…本性的；…性情的","sc":"-natured","ex":{"en":"a good-natured man","cn":"脾气好的人"}},{"en":"a British magazine containing news and opinions about science and scientific research, and discussion of issues concerning science. It is well respected, and important new scientific research is often first published in it. It has been published every week since 1869.","cn":"自然：一家英国杂志，其中载有有关科学和科学研究的新闻和观点，以及有关科学问题的讨论。它是受人尊敬的，重要的新科学研究通常会首先在其中发表。自1869年以来，它每周出版一次。","pos":""}]},"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"大自然;自然界","en":"Nature is all the animals, plants, and other things in the world that are not made by people, and all the events and processes that are not caused by people. →see usage note at:","ex":{"en":"The most amazing thing about nature is its infinite variety.","cn":"大自然最让人惊叹的是它的无限多样性。"}},{"pos":"N-SING 单数名词","cn":"本质;性质","en":"The nature of something is its basic quality or character.","ex":{"en":"Mr Sharp would not comment on the nature of the issues being investigated.","cn":"夏普先生不愿就被调查问题的性质发表评论。"}},{"pos":"N-SING 单数名词","cn":"性格;性情;禀性;天性","en":"Someone's nature is their character, which they show by the way they behave.","ex":{"en":"Jeya feels that her ambitious nature made her unsuitable for an arranged marriage","cn":"耶娅觉得她不安分的个性不适合包办的婚姻。"}},{"pos":"PHRASE 短语","cn":"违反自然;反常","en":"If you say that something is against nature, you think that it is unnatural.","ex":{"en":"All these activities are against nature.","cn":"所有这些活动都是违背常理的。"}},{"pos":"PHRASE 短语","cn":"回归自然;返璞归真","en":"If you want to get back to nature, you want to return to a simpler way of living.","ex":{"en":"She was very anxious to get away from cities and back to nature.","cn":"她特别渴望离开城市，回归自然。"}},{"pos":"PHRASE 短语","cn":"按其固有的性质;就其本质","en":"If you say that something has a particular characteristic by its nature or by its very nature, you mean that things of that type always have that characteristic.","ex":{"en":"Peacekeeping, by its nature, makes pre-planning difficult","cn":"维和行动本身的特点决定了预先制订计划很困难。"}},{"pos":"PHRASE 短语","cn":"(委婉说法)内急，需要去洗手间","en":"Some people talk about a call of nature when referring politely to the need to go to the toilet.","ex":{"en":"I'm afraid I have to answer a call of nature.","cn":"抱歉我要去趟洗手间。"}},{"pos":"PHRASE 短语","cn":"理所当然地;必然地","en":"If you say that something is in the nature of things, you mean that you would expect it to happen in the circumstances mentioned.","ex":{"en":"Of course, in the nature of things, and with a lot of drinking going on, people failed to notice","cn":"喝了那么多酒，大家当然没能察觉到。"}},{"pos":"PHRASE 短语","cn":"具有…性质的;与…类似的;…之类的","en":"If you say that one thing is in the nature of another, you mean that it is like the other thing.","ex":{"en":"There is movement towards, I think, something in the nature of a pluralistic system","cn":"我想，出现了某种向类似多元体系转变的趋势。"}},{"pos":"PHRASE 短语","cn":"第二天性;习性","en":"If a way of behaving is second nature to you, you do it almost without thinking because it is easy for you or obvious to you.","ex":{"en":"Planning ahead had always come as second nature to her","cn":"预先计划一直是她的习惯。"}}]},"examples":[{"en":"In the nature of things, young people often rebel against their parents.","cn":"年轻人常常会反抗他们的父母，这很自然。"},{"en":"Her illness was Nature's way of telling her to do less.","cn":"她的疾病是天意在告诉她不要太劳累。"}]},"narrator":{"media":{"uk":"media/uk/narrator__gb_1.mp3","us":"media/us/narrator__us_1.mp3"},"oxford":{"phon":"nəˈreɪtə(r)","pos":"noun","senses":[{"en":"a person who tells a story, especially in a book, play or film; the person who speaks the words in a television programme but who does not appear in it","cn":"（书、戏剧或电影中的）叙述者，讲述者；（电视节目中的）幕后解说员，旁白员","ex":{"en":"a first-person narrator","cn":"第一人称叙述者"}}]},"examples":[{"en":"a first-person narrator","cn":"第一人称叙述者"}]},"narrow":{"media":{"uk":"media/uk/narrow__gb_1.mp3","us":"media/us/narrow__us_1.mp3"},"oxford":{"phon":"ˈnærəʊ","pos":"adjective","senses":[{"en":"measuring a short distance from one side to the other, especially in relation to length","cn":"狭窄的；窄小的","lab":"figurative","ex":{"en":"Stray dogs wander the steep narrow lanes of the old town.","cn":"流浪狗在老城区陡峭狭窄的小巷里徘徊。"}},{"en":"only just achieved or avoided","cn":"勉强的；刚刚好的","g":"[usually before noun]","ex":{"en":"a narrow victory","cn":"险胜"}},{"en":"limited in variety or numbers","cn":"（种类或数目）有限的；范围小的","ex":{"en":"The shop sells only a narrow range of goods.","cn":"这家商店商品的种类有限。"}},{"en":"limited in a way that ignores important issues or the opinions of other people","cn":"狭隘的；目光短浅的","ex":{"en":"narrow interests","cn":"目光短浅的利益"}},{"en":"limited in meaning; exact","cn":"狭义的；严格的；准确的","ex":{"en":"I am using the word ‘education’ in the narrower sense.","cn":"我说的是较狭义的“教育”。"}},{"en":"to become or make something less wide","cn":"使窄小；变窄；缩小","ex":{"en":"This is where the river narrows.","cn":"河是在这里变窄的。"},"pos":"verb"},{"en":"to become or make something more limited in range or extent","cn":"缩小（范围）","ex":{"en":"The gap between the candidates has narrowed significantly.","cn":"候选人之间的差距明显缩小。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"狭窄的;狭小的","en":"Something that is narrow measures a very small distance from one side to the other, especially compared to its length or height.","ex":{"en":"...through the town's narrow streets","cn":"穿过该镇狭窄的街道"}},{"pos":"VERB 动词","cn":"变狭窄;变窄","en":"If something narrows, it becomes less wide.","ex":{"en":"The wide track narrows before crossing another stream.","cn":"宽宽的小径在穿过另一条小溪前逐渐收窄。"}},{"pos":"V-ERG 及物/不及物动词","cn":"(使)(眼睛)眯起","en":"If your eyes narrow or if you narrow your eyes, you almost close them, for example because you are angry or because you are trying to concentrate on something.","ex":{"en":"Coggins' eyes narrowed angrily. 'You think I'd tell you?'","cn":"科金斯气得眯起眼睛。“你认为我会告诉你？”"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(想法、态度或信仰)狭隘的，有局限的","en":"If you describe someone's ideas, attitudes, or beliefs as narrow, you disapprove of them because they are restricted in some way, and often ignore the more important aspects of an argument or situation.","ex":{"en":"...a narrow and outdated view of family life","cn":"对家庭生活狭隘过时的看法"}},{"pos":"V-ERG 及物/不及物动词","cn":"缩小;(使)变小","en":"If something narrows or if you narrow it, its extent or range becomes smaller.","ex":{"en":"Most recent opinion polls suggest that the gap between the two main parties has narrowed","cn":"最新的民意测验显示这两大主要政党之间的差距已经缩小了。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(胜利)勉强的;(胜负)差距微弱的;险胜的","en":"If you have a narrow victory, you succeed in winning but only by a small amount.","ex":{"en":"Delegates have voted by a narrow majority in favour of considering electoral reform.","cn":"代表们投票表决，以微弱多数票赞同考虑选举制度的改革。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"很险的;勉强的","en":"If you have a narrow escape, something unpleasant nearly happens to you.","ex":{"en":"Two police officers had a narrow escape when separatists attacked their vehicles.","cn":"分裂主义者袭击他们的车辆时，两名警官死里逃生。"}},{"pos":"","cn":"","en":"→see: ;"},{"pos":"","cn":"","en":"相关词组：narrow down"}]},"examples":[{"en":"We need to try and narrow the health divide between rich and poor.","cn":"我们需要设法缩小穷人和富人之间的健康差距。"},{"en":"His attitudes show a certain narrowness of mind.","cn":"他的态度显示他的思想有些狭隘。"}]},"navigating":{"oxford":{"phon":"ˈnævɪɡeɪt","pos":"verb","senses":[{"en":"to find your position or the position of your ship, plane, car etc. and the direction you need to go in, for example by using a map","cn":"导航；确定（船、飞机、汽车等）的位置和方向"},{"en":"to sail along, over or through a sea, river etc.","cn":"航行；航海；横渡"}]}},"nasty":{"media":{"uk":"media/uk/nasty__gb_1.mp3","us":"media/us/nasty__us_1.mp3"},"oxford":{"phon":"ˈnɑːsti","pos":"adjective","senses":[{"en":"very bad or unpleasant","cn":"极差的；令人厌恶的；令人不悦的","ex":{"en":"He had a nasty accident.","cn":"他出了严重的事故。"}},{"en":"unkind; unpleasant","cn":"不友好的；恶意的；令人不愉快的","ex":{"en":"She's always making nasty remarks about people.","cn":"她总是说别人的坏话。"}},{"en":"dangerous or serious","cn":"危险的；严重的","ex":{"en":"a nasty bend (= dangerous for cars going fast)","cn":"危险的弯道"}},{"en":"offensive; in bad taste","cn":"无礼的；污秽的；下流的","ex":{"en":"to have a nasty mind","cn":"思想肮脏"}}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人不快的;令人厌恶的;恶劣的","en":"Something that is nasty is very unpleasant to see, experience, or feel.","ex":{"en":"...an extremely nasty murder","cn":"令人发指的谋杀"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"恶毒的;恶意的;凶相的","en":"If you describe a person or their behaviour as nasty, you mean that they behave in an unkind and unpleasant way.","ex":{"en":"What nasty little snobs you all are","cn":"你们全都是些可恶的势利小人。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"邋遢的;低劣的;下流的;污秽的","en":"If you describe something as nasty, you mean it is unattractive, undesirable, or in bad taste.","ex":{"en":"...Emily's nasty little house in Balham","cn":"埃米莉在巴勒姆的脏乱小屋"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"令人担忧的;难对付的","en":"A nasty problem or situation is very worrying and difficult to deal with.","ex":{"en":"A spokesman said this firm action had defused a very nasty situation.","cn":"一位发言人称这一坚决的行动缓和了极为棘手的局面。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"(伤口、疾病等)严重的，恶性的","en":"If you describe an injury or a disease as nasty, you mean that it is serious or looks unpleasant.","ex":{"en":"My little granddaughter caught her heel in the spokes of her bicycle — it was a very nasty wound","cn":"我小孙女的脚跟夹到自行车的轮辐里了，伤得很严重。"}},{"pos":"N-PLURAL 复数名词","cn":"令人不快的人(或事);危害别人的人(或事)","en":"Nasties are unpleasant or harmful people or things.","ex":{"en":"...evil organisations, peopled with nasties","cn":"充斥着恶棍的邪恶组织"}}]},"examples":[{"en":"I had a nasty feeling that he would follow me.","cn":"我觉得他会跟着我，这使我感到十分不快。"},{"en":"Don't buy that coat — it looks cheap and nasty.","cn":"别买那件外套，一看就是差劲的便宜货。"}]},"naturalist":{"media":{"uk":"media/uk/naturalist__gb_1.mp3","us":"media/us/naturalist__us_1.mp3"},"oxford":{"phon":"ˈnætʃrəlɪst","pos":"noun","senses":[{"en":"a person who studies animals, plants, birds and other living things","cn":"博物学家"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"博物学家","en":"A naturalist is a person who studies plants, animals, insects, and other living things."}]}},"nan":{"media":{"uk":"media/uk/nan__gb_1.mp3","us":"media/us/nan__us_1.mp3"},"oxford":{"phon":"næn","pos":"noun","senses":[{"en":"a grandmother","cn":"奶奶；姥姥"},{"en":"a type of flat bread found in the cuisines (= cooking styles) of many parts of Asia","cn":"馕"}]},"collins":{"senses":[{"pos":"N-COUNT; N-VOC 可数名词；称呼名词","cn":"奶奶;姥姥","en":"Some people refer to their grandmother as their nan .","ex":{"en":"I was brought up by my nan.","cn":"我是奶奶带大的。"}}]}},"narrate":{"media":{"uk":"media/uk/narrate__gb_1.mp3","us":"media/us/narrate__us_1.mp3"},"oxford":{"phon":"nəˈreɪt","pos":"verb","senses":[{"en":"to tell a story","cn":"讲（故事）；叙述","lab":"formal","ex":{"en":"She entertained them by narrating her adventures in Africa.","cn":"她讲述她在非洲的历险来逗他们开心。"}},{"en":"to speak the words that form the text of a documentary film or programme","cn":"给（纪录片或节目）解说","ex":{"en":"The film was narrated by Andrew Sachs.","cn":"这部电影是由安德鲁·萨克斯解说的。"}}]},"collins":{"senses":[{"pos":"VERB 动词","cn":"叙述;讲述","en":"If you narrate a story, you tell it from your own point of view.","ex":{"en":"The three of them narrate the same events from three perspectives","cn":"他们三人从三个不同的视角讲述了同样的事件。"}},{"pos":"VERB 动词","cn":"给(电影或节目)作解说","en":"The person who narrates a film or programme speaks the words which accompany the pictures, but does not appear in it.","ex":{"en":"She also narrated a documentary about the Kirov Ballet School.","cn":"她还为一部关于基洛夫芭蕾舞学院的纪录片作过解说。"}}]},"examples":[{"en":"The film was narrated by Andrew Sachs.","cn":"这部电影是由安德鲁 · 萨克斯解说的。"},{"en":"She entertained them by narrating her adventures in Africa.","cn":"她讲述她在非洲的历险来逗他们开心。"}]},"navigate":{"oxford":{"phon":"ˈnævɪɡeɪt","pos":"verb","senses":[{"en":"to plan and direct the course of ship, plane, car etc., for example by using a map","cn":"导航；确定（船、飞机、汽车等）的位置和方向","g":"[intransitive, transitive]","ex":{"en":"to navigate by the stars","cn":"根据星辰确定航向"}},{"en":"to sail along, over or through a sea, river etc.","cn":"航行；航海；横渡","g":"[transitive]","ex":{"en":"The river became too narrow and shallow to navigate.","cn":"河道变得又窄又浅，无法航行。"}},{"en":"to find the right way to deal with a difficult or complicated situation","cn":"正确处理，有效应对（困难或复杂的情况）","g":"[transitive]","ex":{"en":"We next had to navigate a complex network of committees.","cn":"我们下一步必须设法使各级委员会予以通过。"}},{"en":"to find your way around on the internet or on a particular website","cn":"浏览（网站）","g":"[intransitive, transitive]","lab":"computing","ex":{"en":"Customers will be able to navigate easily throughout the site.","cn":"顾客将能够轻松查阅网站信息。"}}]},"collins":{"senses":[{"pos":"V-ERG 及物/不及物动词","cn":"为(船只、飞机等)导航;确定…的航行方向;(船只、飞机等)驶向","en":"When someone navigates a ship or an aircraft somewhere, they decide which course to follow and steer it there. You can also say that a ship or an aircraft navigates somewhere.","ex":{"en":"Captain Cook safely navigated his ship without accident for 100 voyages","cn":"库克船长驾驶的船安全出航100次无事故。"}},{"pos":"VERB 动词","cn":"(船只)航行于，横渡","en":"When a ship or boat navigates an area of water, it sails on or across it.","ex":{"en":"...a lock system to allow sea-going craft to navigate the upper reaches of the river","cn":"使海轮可以进入河流上游地区航行的河闸控制系统"}},{"pos":"VERB 动词","cn":"(驾车者)确定行车路线","en":"When someone in a car navigates, they decide what roads the car should be driven along in order to get somewhere.","ex":{"en":"When travelling on fast roads at night it is impossible to drive and navigate at the same time.","cn":"晚上在高速路上行驶时根本做不到边开车边找路。"}},{"pos":"VERB 动词","cn":"(鱼、动物或昆虫)找到正确的行动方向","en":"When fish, animals, or insects navigate somewhere, they find the right direction to go and travel there.","ex":{"en":"In tests, the bees navigate back home after being placed in a field a mile away.","cn":"在多次试验中，放置于一英里以外田野中的蜜蜂都能飞回蜂巢。"}},{"pos":"VERB 动词","cn":"小心翼翼地绕过(障碍)","en":"If you navigate an obstacle, you move carefully in order to avoid hitting the obstacle or hurting yourself.","ex":{"en":"He was not able to walk without a cane and could only navigate steps backwards","cn":"没有手杖他无法走路，只能小心翼翼地向后退。"}},{"pos":"VERB 动词","cn":"驾驭，成功应付(困难处境)","en":"If you manage to navigate a difficult situation, you deal with it successfully.","ex":{"en":"During childhood each of us has to navigate a pathway through a series of developmental stages","cn":"我们每个人在童年时都要经历和应对不同的成长阶段。"}}]},"media":{"uk":"media/uk/navigate__gb_1.mp3","us":"media/us/navigate__us_1.mp3"},"examples":[{"en":"We next had to navigate a complex network of committees.","cn":"我们下一步必须设法使各级委员会予以通过。"},{"en":"The river became too narrow and shallow to navigate.","cn":"河道变得又窄又浅，无法航行。"}]},"native":{"media":{"uk":"media/uk/native__gb_1.mp3","us":"media/us/native__us_1.mp3"},"oxford":{"phon":"ˈneɪtɪv","pos":"adjective","senses":[{"en":"connected with the place where you were born and lived for the first years of your life","cn":"出生地的；儿时居住地的","g":"[only before noun]","ex":{"en":"your native land/country/city","cn":"你的故乡／祖国／故里"}},{"en":"connected with the place where you have always lived or have lived for a long time","cn":"本地的；当地的","g":"[only before noun]","ex":{"en":"native Berliners","cn":"土生土长的柏林人"}},{"en":"connected with the people who originally lived in a country before other people, especially white people, came there","cn":"土著的；土著人的","g":"[only before noun]","lab":"sometimes offensive","ex":{"en":"The native peoples depend on the forest for their livelihoods.","cn":"土著族群以森林为生。"}},{"en":"existing naturally in a place","cn":"原产于某地的；土产的；当地的","ex":{"en":"the native plants of America","cn":"美国的土生植物"}},{"en":"that you have naturally without having to learn it","cn":"天赋的；与生俱来的","g":"[only before noun]","ex":{"en":"native cunning","cn":"与生俱来的狡猾"}},{"en":"found in a pure state","cn":"自然的","ex":{"en":"native gold/silver/copper","cn":"自然金／银／铜"}},{"en":"designed for or built into a particular system, especially using the language or computer code associated with a particular computer or processor","cn":"本地的；本机的","lab":"computing","ex":{"en":"Native apps still generally perform better than web apps, but the gap is shrinking.","cn":"原生应用程序通常仍然比网络应用程序表现更好，但差距正在缩小。"}},{"en":"a person who was born in a particular country or area","cn":"出生于某国（或某地）的人","ex":{"en":"a native of New York","cn":"纽约人"},"pos":"noun"},{"en":"a person who lives in a particular place, especially somebody who has lived there a long time","cn":"本地人；当地人","ex":{"en":"You can always tell the difference between the tourists and the natives.","cn":"游客与当地人之间的区别一望即知。"},"pos":"noun"},{"en":"a word used in the past by Europeans to describe a person who lived in a place originally, before white people arrived there","cn":"（旧时欧洲人用以称呼先于白人居住在某地的人）土著","lab":"offensive, old-fashioned，，","ex":{"en":"disputes between early settlers and natives","cn":"早期移民和土著之间的纷争"},"pos":"noun"},{"en":"an animal or a plant that lives or grows naturally in a particular area","cn":"本地的动物（或植物）","ex":{"en":"The kangaroo is a native of Australia.","cn":"袋鼠是产于澳大利亚的动物。"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":". 出生地的;儿时居住的","en":"Your native country or area is the country or area where you were born and brought up","ex":{"en":"It was his first visit to his native country since 1948","cn":"这是自1948年以来他首次回到自己的祖国。"}},{"pos":"N-COUNT 可数名词","cn":"本国人;本地人","en":"A native of a particular country or region is someone who was born in that country or region.","ex":{"en":"Dr Aubin is a native of St Blaise.","cn":"奥宾博士是圣布莱斯人。"}},{"pos":"N-COUNT 可数名词","cn":"土人，土著(一些欧洲人指非西方国家的原住民，可能具冒犯意味)","en":"Some European people use native to refer to a person living in a non-Western country who belongs to the race or tribe that the majority of people there belong to. This use could cause offence.","ex":{"en":"They used force to banish the natives from the more fertile land.","cn":"他们使用武力把土著居民驱逐出了比较肥沃的土地。"}},{"pos":"ADJ 形容词","cn":"(语言)本国的，出生地的","en":"Your native language or tongue is the first language that you learned to speak when you were a child.","ex":{"en":"She spoke not only her native language, Swedish, but also English and French","cn":"她不仅讲自己的母语瑞典语，还讲英语和法语。"}},{"pos":"ADJ 形容词","cn":"(动植物)当地土生的，原产地的","en":"Plants or animals that are native to a particular region live or grow there naturally and were not brought there.","ex":{"en":"...a project to create a 50 acre forest of native Caledonian pines","cn":"营造50英亩喀里多尼亚土生松树林的项目"}},{"pos":"ADJ 形容词","cn":"(能力或品质)生来就有的，天赋的","en":"A native ability or quality is one that you possess naturally without having to learn it.","ex":{"en":"We have our native inborn talent, yet we hardly use it.","cn":"我们有天生的才能，但我们却几乎未曾使用过。"}},{"pos":"PHRASE 短语","cn":"(移居他国的人)入乡随俗，同化","en":"If you say that someone who is living away from their own country goes native, you mean that they try to live and dress like the local people.","ex":{"en":"You don't think he's gone native, do you? Perhaps he has married out there and decided he can't come home.","cn":"你觉得他并没有入乡随俗，是吗？可能他和那里的人结了婚，认定回不了家了。"}}]},"examples":[{"en":"You can always tell the difference between the tourists and the natives.","cn":"游客与当地人之间的区别一望即知。"},{"en":"She speaks Italian like a native.","cn":"她的意大利语说得和意大利人一样。"}]},"naturally":{"media":{"uk":"media/uk/naturally__gb_1.mp3","us":"media/us/naturally__us_1.mp3"},"oxford":{"phon":"ˈnætʃrəli","pos":"adverb","senses":[{"en":"in a way that you would expect","cn":"自然地；当然地","ex":{"en":"Naturally, I get upset when things go wrong.","cn":"事情出了错，我当然就会很烦。"}},{"en":"without special help, treatment or action by somebody","cn":"天然地；自然而然地","ex":{"en":"naturally occurring chemicals","cn":"天然存在的化学物质"}},{"en":"as a normal, logical result of something","cn":"合理地；理所当然地；顺理成章地","ex":{"en":"This leads naturally to my next point.","cn":"这必然引出我的下一个论点。"}},{"en":"in a way that shows or uses abilities or qualities that a person or an animal is born with","cn":"天生地；本能地","ex":{"en":"to be naturally artistic","cn":"有艺术天赋"}},{"en":"in a relaxed and normal way","cn":"自然地；大方地","ex":{"en":"Just act naturally.","cn":"放自然点儿就行了。"}}]},"collins":{"senses":[{"pos":"ADV 副词","cn":"自然地;当然地","en":"You use naturally to indicate that you think something is very obvious and not at all surprising in the circumstances.","ex":{"en":"When things go wrong, all of us naturally feel disappointed and frustrated","cn":"出问题时，我们大家自然都感到失望和沮丧。"}},{"pos":"ADV 副词","cn":"自然地;合理地;顺理成章地","en":"If one thing develops naturally from another, it develops as a normal consequence or result of it.","ex":{"en":"A study of yoga leads naturally to meditation.","cn":"学习瑜伽自然会发展到进行冥想。"}},{"pos":"ADV 副词","cn":"大方地;自然地","en":"You can use naturally to talk about a characteristic of someone's personality when it is the way that they normally act.","ex":{"en":"He has a lively sense of humour and appears naturally confident.","cn":"他有一种活泼外向的幽默感，看上去大方自信。"}},{"pos":"ADV 副词","cn":"轻而易举地;天生地","en":"If someone is naturally good at something, they learn it easily and quickly and do it very well.","ex":{"en":"Some individuals are naturally good communicators.","cn":"一些人天生善于交流沟通。"}},{"pos":"PHRASE 短语","cn":"(对…而言)轻而易举","en":"If something comes naturally to you, you find it easy to do and quickly become good at it.","ex":{"en":"With football, it was just something that came naturally to me.","cn":"说起踢足球，对我来说再容易不过。"}}]},"examples":[{"en":"After a while, we naturally started talking about the children.","cn":"过了一会儿，我们自然而然地谈起了孩子。"},{"en":"‘Did you complain about the noise?’ ‘Naturally.’ “","cn":"你是不是嫌吵了？” “那还用说。”"}]},"naive":{"media":{"uk":"media/uk/naive__gb_1.mp3","us":"media/us/naive__us_1.mp3"},"oxford":{"phon":"naɪˈiːv","pos":"adjective","senses":[{"en":"not showing enough knowledge, good judgement or experience of life; too willing to believe that people always tell you the truth","cn":"缺乏经验的；幼稚的；无知的；轻信的","lab":"disapproving","ex":{"en":"to be politically naive","cn":"对政治无知"}},{"en":"innocent and simple","cn":"天真的；率直的","lab":"approving","ex":{"en":"Their approach to life is refreshingly naive.","cn":"他们对待生活的态度天真率直，令人耳目一新。"}},{"en":"in a style which is deliberately very simple, often uses bright colours and is similar to that produced by a child","cn":"稚拙派的（简单质朴，色彩明快）","lab":"specialist"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"天真的;幼稚的","en":"If you describe someone as naive, you think they lack experience and so expect things to be easy or people to be honest or kind.","ex":{"en":"It's naive to think that teachers are always tolerant","cn":"认为老师们总那么宽容是幼稚的。"}}]},"examples":[{"en":"Their approach to life is refreshingly naive.","cn":"他们对待生活的态度天真率直，令人耳目一新。"},{"en":"I can't believe you were so naive as to trust him!","cn":"真是难以相信你会幼稚到信任他！"}]},"narrative":{"media":{"uk":"media/uk/narrative__gb_1.mp3","us":"media/us/narrative__us_1.mp3"},"oxford":{"phon":"ˈnærətɪv","pos":"noun","senses":[{"en":"a description of events","cn":"叙述；讲述","g":"[countable]","lab":"US English","ex":{"en":"a gripping narrative of their journey up the Amazon","cn":"他们沿亚马孙河而上的扣人心弦的描述"}},{"en":"the part of a novel that tells the story, rather than the dialogue","cn":"（小说的）叙述，描述","g":"[uncountable]","ex":{"en":"The novel contains too much dialogue and not enough narrative.","cn":"这部小说对话过多，而叙述不足。"}},{"en":"a way of explaining events to illustrate a set of aims or values","cn":"论述","g":"[countable, uncountable]","ex":{"en":"a new narrative about economic globalization","cn":"经济全球化新解"}},{"en":"describing events or telling a story","cn":"描述的；叙述的","ex":{"en":"narrative fiction","cn":"叙事小说"},"pos":"adjective"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"故事;叙事","en":"A narrative is a story or an account of a series of events.","ex":{"en":"...a fast-moving narrative","cn":"快节奏的叙事"}},{"pos":"N-UNCOUNT 不可数名词","cn":"(通常指小说中一系列事件的)记叙，叙述，讲述","en":"Narrative is the description of a series of events, usually in a novel.","ex":{"en":"Neither author was very strong on narrative.","cn":"两个作者都不是很善于讲故事。"}}]},"examples":[{"en":"a gripping narrative of their journey up the Amazon","cn":"他们沿亚马逊河而上的扣人心弦的描述"},{"en":"The novel contains too much dialogue and not enough narrative.","cn":"这部小说对话过多，而叙述不足。"}]},"nancy":{"oxford":{"phon":"ˈnænsi","pos":"noun","senses":[{"en":"an offensive word for a gay man, or a man who behaves in a way that is thought to be typical of women","cn":"假娘儿们（含冒犯意，指同性恋男子或举止像女性的男子）"},{"en":"a first name for girls","cn":"南希（女子名）","pos":""}]},"media":{"uk":"media/uk/nancy__gb_1.mp3","us":"media/us/nancy__us_1.mp3"}},"naked":{"media":{"uk":"media/uk/naked__gb_1.mp3","us":"media/us/naked__us_1.mp3"},"oxford":{"phon":"ˈneɪkɪd","pos":"adjective","senses":[{"en":"not wearing any clothes","cn":"裸体的","ex":{"en":"She was clutching the sheet around her naked body.","cn":"那时她正紧紧抓着床单，裹住自己赤裸的身体。"}},{"en":"with nothing to cover it","cn":"无遮盖的","g":"[usually before noun]","lab":"British English","ex":{"en":"a naked light","cn":"无罩灯"}},{"en":"expressed strongly and not hidden","cn":"直白的；露骨的；毫不掩饰的","g":"[only before noun]","ex":{"en":"naked aggression","cn":"赤裸裸的攻击"}},{"en":"unable to protect yourself from being harmed, criticized, etc.","cn":"缺乏保护；无力自卫","g":"[not usually before noun]","ex":{"en":"He still felt naked and drained after his ordeal.","cn":"经历了这场磨难之后，他仍然感到无法自卫，而且筋疲力尽。"}}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"裸露的;赤身裸体的","en":"Someone who is naked is not wearing any clothes.","ex":{"en":"Her naked body was found wrapped in a sheet in a field","cn":"在田里发现了她的尸体，全身赤裸，裹在一条床单里。"}},{"pos":"ADJ 形容词","cn":"(动物)没有皮毛的，没有羽毛的","en":"If an animal or part of an animal is naked, it has no fur or feathers on it.","ex":{"en":"The nest contained eight little mice that were naked and blind.","cn":"窝里有8只还没长毛、眼睛尚未睁开的小老鼠。"}},{"pos":"ADJ 形容词","cn":"赤手空拳的;无防备的","en":"If you say that someone is naked or feels naked, you mean they are powerless or have no way of protecting themselves.","ex":{"en":"If the reports are accurate, the deal leaves the authorities and the President virtually naked.","cn":"如果报道属实，此交易的确使当局和总统猝不及防。"}},{"pos":"ADJ 形容词","cn":"无遮蔽的;无覆盖的","en":"You can describe an object as naked when it does not have its normal covering.","ex":{"en":"...a naked bulb dangling in a bare room","cn":"空荡荡的房间里吊着的一只没有灯罩的灯泡"}},{"pos":"ADJ 形容词","cn":"(情感)明显的，直率的","en":"Naked emotions are easy to recognize, because they are very strongly felt.","ex":{"en":"The naked hatred in the woman's face shocked me","cn":"那位女士一脸毫不掩饰的憎恨让我震惊。"}},{"pos":"ADJ 形容词","cn":"公然的;赤裸裸的","en":"You can use naked to describe unpleasant or violent actions and behaviour which are not disguised or hidden in any way.","ex":{"en":"Naked aggression and an attempt to change frontiers by force could not go unchallenged.","cn":"公然的侵略和企图用武力改变边界的行径是不能置之不理的。"}},{"pos":"PHRASE 短语","cn":"(观察时)用肉眼，用裸眼","en":"If you say that something cannot be seen by the naked eye, you mean that it cannot be seen without the help of equipment such as a telescope or microscope.","ex":{"en":"The worms cannot be seen by the naked eye","cn":"这些虫子用肉眼看不见。"}}]},"examples":[{"en":"He still felt naked and drained after his ordeal.","cn":"经历了这场磨难之后，他仍然感到无法自卫，而且筋疲力尽。"},{"en":"They found him half naked and bleeding to death.","cn":"他们发现他身体半裸，流着血，快不行了。"}]},"nationally":{"media":{"uk":"media/uk/nationally__gb_1.mp3","us":"media/us/nationally__us_1.mp3"},"oxford":{"phon":"ˈnæʃnəli","pos":"adverb","senses":[{"en":"relating to a country as a whole; relating to a particular country","cn":"全国性地；与某国相关地","ex":{"en":"The programme was broadcast nationally.","cn":"这个节目曾在全国播放过。"}}]},"examples":[{"en":"He's a talented athlete who competes nationally and internationally.","cn":"他是一位有才华的运动员，既参加国内比赛，也参加国际比赛。"},{"en":"Meetings were held locally and nationally.","cn":"举行的会议有地方性的，也有全国性的。"}]},"naan":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"印度烤饼","en":"Naan or naan bread is a type of bread that comes in a large, round, flat piece and is usually eaten with Indian food.","ex":{"en":"...traditional dishes, such as rogan josh, served with rice or naan.","cn":"配米饭或印度烤饼吃的传统菜肴，如咖喱羊肉等"}}]},"media":{"uk":"media/uk/naan__gb_1.mp3","us":"media/us/naan__us_1.mp3"},"oxford":{"phon":"nɑːn","pos":"noun","senses":[{"en":"a type of flat bread found in the cuisines (= cooking styles) of many parts of Asia","cn":"馕"}]}},"napkin":{"media":{"uk":"media/uk/napkin__gb_1.mp3","us":"media/us/napkin__us_1.mp3"},"oxford":{"phon":"ˈnæpkɪn","pos":"noun","senses":[{"en":"a piece of cloth or paper used at meals for protecting your clothes and cleaning your lips and fingers","cn":"餐巾；餐巾纸","ex":{"en":"He tucked his napkin under his chin.","cn":"他把餐巾掖到下巴底下。"}},{"en":"a thick piece of soft material that a woman wears between her legs to hold blood during her period","cn":"卫生巾","lab":"both North American English"},{"en":"a nappy (= a piece of soft cloth or other thick material that is folded around a baby’s bottom and between its legs to take in and hold its body waste)","cn":"尿布","lab":"British English, old-fashioned or formal，，"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"餐巾;餐巾纸","en":"A napkin is a square of cloth or paper that you use when you are eating to protect your clothes, or to wipe your mouth or hands.","ex":{"en":"She was taking tiny bites of a hot dog and daintily wiping her lips with a napkin.","cn":"她小口地吃着热狗，用餐巾优雅地擦着嘴。"}}]}},"name":{"media":{"uk":"media/uk/name__gb_1.mp3","us":"media/us/name__us_1.mp3"},"oxford":{"phon":"neɪm","pos":"noun","senses":[{"en":"a word or words that a particular person, animal, place or thing is known by","cn":"名字；名称","lab":"British English","ex":{"en":"What's your name?","cn":"你叫什么名字？"}},{"en":"a reputation that somebody/something has; the opinion that people have about somebody/something","cn":"名誉；名声；名气","g":"[usually singular]","ex":{"en":"She first made her name as a writer of children's books.","cn":"她最初是以儿童读物作家成名的。"}},{"en":"having a name or a reputation of the kind mentioned, especially one that is known by a lot of people","cn":"有…名称的；以…著名的；有…名声的","ex":{"en":"a big-name company","cn":"著名公司"}},{"en":"a famous person","cn":"名人","ex":{"en":"He is a big name in the world of rock music.","cn":"他在摇滚乐界颇有名气。"}},{"en":"to give a name to somebody/something","cn":"命名；给…取名","g":"[often passive]","ex":{"en":"He was named after his father (= given his father's first name).","cn":"他的名字跟他父亲一样。"},"pos":"verb"},{"en":"to say the name of somebody/something","cn":"说出…的名称；叫出…的名字","ex":{"en":"The victim has not yet been named.","cn":"受害人的姓名尚未公布。"},"pos":"verb"},{"en":"to state something exactly","cn":"确定；说定；准确陈述","ex":{"en":"Name your price.","cn":"给个价吧。"},"pos":"verb"},{"en":"to choose somebody for a job or position","cn":"任命；委任","ex":{"en":"I had no hesitation in naming him (as) captain.","cn":"我毫不犹豫地任命他为队长。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"名字;名称;姓名","en":"The name of a person, place, or thing is the word or group of words that is used to identify them.","ex":{"en":"'What's his name?'—'Peter.'","cn":"“他叫什么？”——“彼得。”"}},{"pos":"VERB 动词","cn":"给…取名;给…命名","en":"When you name someone or something, you give them a name, usually at the beginning of their life.","ex":{"en":"My mother insisted on naming me Horace.","cn":"我母亲坚持给我取名叫霍勒斯。"}},{"pos":"VERB 动词","cn":"(以…)为…命名","en":"If you name someone or something after another person or thing, you give them the same name as that person or thing.","ex":{"en":"Why have you not named any of your sons after yourself?","cn":"为什么没让哪个儿子用你的名字呢？"}},{"pos":"VERB 动词","cn":"叫出…的名称;说出…的名字","en":"If you name someone, you identify them by stating their name.","ex":{"en":"It's nearly thirty years since a journalist was jailed for refusing to name a source","cn":"一名记者因拒绝说出消息来源而入狱已经是近30年前的事了。"}},{"pos":"VERB 动词","cn":"提出，说出，指出(价格、时间、地点等)","en":"If you name something such as a price, time, or place, you say what you want it to be.","ex":{"en":"Call Marty, tell him to name his price.","cn":"给马蒂打电话，让他出个价儿。"}},{"pos":"VERB 动词","cn":"提名;任命","en":"If you name the person for a particular job, you say who you want to have the job.","ex":{"en":"The England manager will be naming a new captain, to replace the injured David Beckham","cn":"英格兰队主教练将任命新队长，接替受伤的大卫·贝克汉姆。"}},{"pos":"N-COUNT 可数名词","cn":"名声;名望;声誉","en":"You can refer to the reputation of a person or thing as their name .","ex":{"en":"He had a name for good judgement","cn":"他以判断准确而闻名。"}},{"pos":"N-COUNT 可数名词","cn":"名人;红人","en":"You can refer to someone as, for example, a famous name or a great name when they are well-known.","ex":{"en":"...some of the most famous names in modelling and show business.","cn":"模特和时装界一些最知名的红人"}},{"pos":"PHRASE 短语","cn":"以…的名义;在…的名下","en":"If something is in someone's name, it officially belongs to them or is reserved for them.","ex":{"en":"The house is in my husband's name","cn":"房子是我丈夫名下的。"}},{"pos":"PHRASE 短语","cn":"代表;以…的名义","en":"If someone does something in the name of a group of people, they do it as the representative of that group.","ex":{"en":"In the United States the majority governs in the name of the people","cn":"在美国，多数派代表民众执政。"}},{"pos":"PHRASE 短语","cn":"籍…为由;以…为名","en":"If you do something in the name of an ideal or an abstract thing, you do it in order to preserve or promote that thing.","ex":{"en":"...one of those rare occasions in history when a political leader risked his own power in the name of the greater public good","cn":"历史上少有的例子之一，政治领袖为更大的公共利益，甘冒丢官弃职的风险"}},{"pos":"PHRASE 短语","cn":"(加强提问或要求的语气)看在(上帝、人道等)的份儿上","en":"People sometimes use expressions such as 'in the name of heaven' or 'in the name of humanity' to add emphasis to a question or request.","ex":{"en":"What in the name of heaven's going on?","cn":"看在上帝份儿上，这到底是怎么回事？"}},{"pos":"PHRASE 短语","cn":"有实无名的;未被认可的","en":"If you say that a situation exists in all but name, you mean that it is not officially recognized even though it exists.","ex":{"en":"...the group, which is now a political party in all but name","cn":"这一团体，现在是有实无名的政党"}},{"pos":"PHRASE 短语","cn":"以名字;指名道姓地","en":"When you mention someone or something by name, or address someone by name, you use their name.","ex":{"en":"He greets customers by name and enquires about their health.","cn":"他跟顾客打招呼时直呼其名，并问他们身体可好。"}},{"pos":"PHRASE 短语","cn":"名叫…;以…为名","en":"You can use by name or by the name of when you are saying what someone is called.","ex":{"en":"...a young Australian, Harry Busteed by name","cn":"名叫哈里·巴斯蒂德的澳大利亚年轻人"}},{"pos":"PHRASE 短语","cn":"谩骂;对…口出恶言","en":"If someone calls you names, they insult you by saying unpleasant things to you or about you.","ex":{"en":"At my last school they called me names because I was so slow","cn":"在之前的学校，因为我反应慢，他们骂过我。"}},{"pos":"PHRASE 短语","cn":"最重要的东西;实质","en":"If you say that something is the name of the game, you mean that it is the most important aspect of a situation.","ex":{"en":"Family values are suddenly the name of the game","cn":"家庭价值观突然变得重要起来。"}},{"pos":"PHRASE 短语","cn":"支持，赞同(事业、项目等)","en":"If you lend your name to something such as a cause or project, you support it.","ex":{"en":"He had political points of view and lent his name to a lot of causes.","cn":"他很有政治见解，对很多事业都予以支持。"}},{"pos":"PHRASE 短语","cn":"(因…)成名;(以…)出名","en":"If you make a name for yourself or make your name as something, you become well-known for that thing.","ex":{"en":"She was beginning to make a name for herself as a portrait photographer","cn":"她开始成为一个小有名气的人像摄影师。"}},{"pos":"PHRASE 短语","cn":"点出(或指出)(做错事者)的名字","en":"If you name names, you identify the people who have done something, often something wrong.","ex":{"en":"Nobody was prepared to risk prosecution by actually naming names.","cn":"没有人愿意冒着被起诉的风险去真正指认别人。"}},{"pos":"PHRASE 短语","cn":"(指报纸或官方机构)曝光，点名，指名(业绩差或犯错的人)","en":"If something such as a newspaper or an official body names and shames people who have performed badly or who have done something wrong, it identifies those people by name.","ex":{"en":"The government will also name and shame the worst performing airlines.","cn":"政府还将曝光业绩最差的航空公司。"}},{"pos":"PHRASE 短语","cn":"在名义上;有名无实地","en":"If you say that a situation exists in name only, you mean that it does not have the status or position that it claims to have.","ex":{"en":"Many of the groups exist in name only","cn":"许多团体实际上是有名无实。"}},{"pos":"PHRASE 短语","cn":"凡是你说得出的，凡是你能想到的(应有尽有)","en":"You say you name it, usually after or before a list, to indicate that you are talking about a very wide range of things.","ex":{"en":"Pickled cucumbers, jam, pickled berries, tomatoes; you name it, they've got it","cn":"酸黄瓜、果酱、腌浆果、西红柿，凡是你说得出的，他们都有。"}},{"pos":"","cn":"","en":"a name to conjure with→see: ;"}]},"examples":[{"en":"He took my place and got killed. It should have been me — that bullet had my name on it.","cn":"他坐了我的位子而送了命。死的应该是我，那颗子弹是冲着我来的。"},{"en":"He comes from Tighnabruaich — now there's a name to conjure with!","cn":"他来自 Tighnabruaich，这个名字真够拗口的！"}]},"nail":{"media":{"img":["media/pic/tools_diy_comp.jpg","media/thumb/nail.jpg"],"uk":"media/uk/nail__gb_1.mp3","us":"media/us/nail__us_1.mp3"},"oxford":{"phon":"neɪl","pos":"noun","senses":[{"en":"the thin hard layer covering the outer tip of the fingers or toes","cn":"指甲；趾甲","ex":{"en":"Stop biting your nails!","cn":"别咬指甲！"}},{"en":"a small thin pointed piece of metal with a flat head, used for joining pieces of wood together or hanging things on a wall","cn":"钉；钉子","lab":"British English","ex":{"en":"She hammered the nail in.","cn":"她把钉子敲了进去。"}},{"en":"to fasten something to something with a nail or nails","cn":"（用钉子）钉牢，固定","ex":{"en":"I nailed the sign to a tree.","cn":"我将标示牌钉到了一棵树上。"},"pos":"verb"},{"en":"to catch somebody and prove they are guilty of a crime or of doing something bad","cn":"抓获并证明有罪；抓住","lab":"informal","ex":{"en":"The police haven't been able to nail the killer.","cn":"警方还没有抓到杀人凶手。"},"pos":"verb"},{"en":"to prove that something is not true","cn":"证明…不属实；揭露；揭发","lab":"informal","ex":{"en":"We must nail this lie.","cn":"我们一定要戳穿这个谎言。"},"pos":"verb"},{"en":"to achieve something or do something right, especially in sport","cn":"（尤指体育运动中）获得，赢得，击中","lab":"informal","ex":{"en":"He nailed a victory in the semi-finals.","cn":"他在半决赛中获胜。"},"pos":"verb"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"钉子","en":"A nail is a thin piece of metal with one pointed end and one flat end. You hit the flat end with a hammer in order to push the nail into something such as a wall.","ex":{"en":"A mirror hung on a nail above the washstand","cn":"脸盆架上方用钉子挂着一面镜子。"}},{"pos":"VERB 动词","cn":"(用钉子)钉住，钉牢","en":"If you nail something somewhere, you fix it there using one or more nails.","ex":{"en":"Frank put the first plank down and nailed it in place","cn":"弗兰克放下第一块厚木板，把它钉在合适的位置上。"}},{"pos":"N-COUNT 可数名词","cn":"指甲;趾甲","en":"Your nails are the thin hard parts that grow at the ends of your fingers and toes.","ex":{"en":"Keep your nails short and your hands clean.","cn":"常剪指甲，保持双手清洁。"}},{"pos":"VERB 动词","cn":"抓住;逮住;证明…有罪","en":"To nail someone means to catch them and prove that they have been breaking the law.","ex":{"en":"The prosecution still managed to nail him for robberies at the homes of leading industrialists.","cn":"检控方仍设法使其入室抢劫知名实业家们的罪名成立。"}},{"pos":"PHRASE 短语","cn":"冷酷无情的;铁石心肠的;强硬好斗的","en":"If you say that someone is as hard as nails, you mean that they are extremely tough and aggressive, either physically or in their attitude towards other people or other situations.","ex":{"en":"He's a shrewd businessman and hard as nails","cn":"他是一个既精明又铁石心肠的生意人。"}},{"pos":"PHRASE 短语","cn":"正中要害;说得中肯","en":"If you say that someone has hit the nail on the head, you think they are exactly right about something.","ex":{"en":"'I think it would civilize people a bit more if they had decent conditions.' — 'I think you've hit the nail on the head.'","cn":"“我认为，如果人们有良好的环境，就会更有教养一点。”——“我想你说到点子上了。”"}},{"pos":"","cn":"","en":"a nail in the coffin→see: ; to nail your colours to the mast→see: ; to fight tooth and nail→see: ;"},{"pos":"","cn":"","en":"相关词组：nail down nail up"}]},"examples":[{"en":"She says she'll come, but I can't nail her down to a specific time.","cn":"她说要来，但我无法让她敲定具体什么时候来。"},{"en":"All the parties seem anxious to nail down a ceasefire.","cn":"各方面似乎都渴望将停火之事敲定。"}]},"nationwide":{"oxford":{"phon":"ˌneɪʃnˈwaɪd","pos":"adjective, adverb","senses":[{"en":"happening or existing in all parts of a particular country","cn":"全国性的；遍及全国的；全国范围的","ex":{"en":"a nationwide campaign","cn":"全国性运动"}},{"en":"the world's largest building society, with branches in many British towns and cities. It was originally established in 1846 and has been known as Nationwide or Nationwide Building Society since 1970.","cn":"全国范围：世界上最大的建筑协会，在英国许多城镇都有分支机构。它最初成立于1846年，自1970年以来被称为全国性建筑协会。","pos":""}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"全国性的;全国范围的","en":"Nationwide activities or situations happen or exist in all parts of a country.","ex":{"en":"The rising number of car crimes is a nationwide problem.","cn":"汽车犯罪数量不断飙升是全国性的问题。"}}]},"media":{"uk":"media/uk/nationwide__gb_1.mp3","us":"media/us/nationwide__us_1.mp3"},"examples":[{"en":"The company has over 500 stores nationwide.","cn":"这家公司在全国各地有 500 多家商店。"},{"en":"a nationwide campaign","cn":"全国性运动"}]},"nationales":{"oxford":{"phon":"ˈnæʃnəl","pos":"adjective","senses":[{"en":"connected with a particular nation; shared by a whole nation","cn":"国家的；民族的；全国的"},{"en":"owned, controlled or paid for by the government","cn":"国有的；国立的；国营的"}]},"media":{"uk":"media/uk/national__gb_1.mp3","us":"media/us/national__us_1.mp3"}},"nanny":{"media":{"uk":"media/uk/nanny__gb_1.mp3","us":"media/us/nanny__us_1.mp3"},"oxford":{"phon":"ˈnæni","pos":"noun","senses":[{"en":"a person whose job is to take care of young children in the children’s own home","cn":"（儿童家中的）保姆","ex":{"en":"She applied for the job of nanny to the Rickman family.","cn":"她申请担任里克曼一家的保母一职。"}},{"en":"a grandmother","cn":"奶奶；姥姥","lab":"both British English","ex":{"en":"When is Nanny coming to stay?","cn":"奶奶什么时候来住？"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(受雇照看小孩的)保姆，阿姨","en":"A nanny is a woman who is paid by parents to look after their child or children."}]},"examples":[{"en":"When is Nanny coming to stay?","cn":"奶奶什么时候来住？"},{"en":"my nan and grandad","cn":"我的爷爷、奶奶"}]},"narration":{"media":{"uk":"media/uk/narration__gb_1.mp3","us":"media/us/narration__us_1.mp3"},"oxford":{"phon":"nəˈreɪʃn","pos":"noun","senses":[{"en":"the act or process of telling a story, especially in a novel, a film or a play","cn":"（尤指小说、电影或戏剧中的）叙述，讲述","g":"[uncountable, countable]","ex":{"en":"The novel constantly switches between first-person and third-person narration.","cn":"小说不断地在第一人称和第三人称叙述之间切换。"}},{"en":"a description of events that is spoken during a film, a play, etc. or with music","cn":"（电影、戏剧等中对情节的）解说，旁白","g":"[countable]","ex":{"en":"He has recorded the narration for the production.","cn":"他录制了这部作品的解说词。"}}]},"examples":[{"en":"He has recorded the narration for the production.","cn":"他录制了这部作品的解说词。"}]},"navy":{"media":{"uk":"media/uk/navy__gb_1.mp3","us":"media/us/navy__us_1.mp3"},"oxford":{"phon":"ˈneɪvi","pos":"noun","senses":[{"en":"the part of a country’s armed forces that fights at sea, and the ships that it uses","cn":"海军；海军部队","g":"[countable + singular or plural verb]","ex":{"en":"the British and German navies","cn":"英国和德国的海军部队"}},{"en":"a very dark blue colour","cn":"深蓝色","g":"[uncountable]"}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"海军","en":"A country's navy consists of the people it employs to fight at sea, and the ships they use.","ex":{"en":"The government announced an order for three Type 23 frigates for the Royal Navy yesterday","cn":"政府昨天宣布为皇家海军订购3艘23型护卫舰。"}},{"pos":"COLOUR 颜色词","cn":"海军蓝;深蓝色;藏青色","en":"Something that is navy or navy-blue is very dark blue.","ex":{"en":"I mostly wore black or navy trousers.","cn":"我大部分时间穿黑色或深蓝色裤子。"}}]},"examples":[{"en":"The navy is/are considering buying six new warships.","cn":"海军正在考虑购买六艘新战舰。"},{"en":"He's joined the navy/the Navy.","cn":"他参加了海军。"}]},"nation":{"media":{"uk":"media/uk/nation__gb_1.mp3","us":"media/us/nation__us_1.mp3"},"oxford":{"phon":"ˈneɪʃn","pos":"noun","senses":[{"en":"a country considered as a group of people with the same language, culture and history, who live in a particular area under one government","cn":"国家；民族","g":"[countable]","ex":{"en":"European/Arab/Asian nations","cn":"欧洲／阿拉伯／亚洲国家"}},{"en":"all the people in a country","cn":"国民","g":"[singular]","ex":{"en":"The entire nation, it seemed, was watching TV.","cn":"好像全国的人都在看电视。"}},{"en":"a native North American people","cn":"北美原住民","ex":{"en":"Minnesota is home to 11 tribal nations.","cn":"明尼苏达州有 11 个部落国家。"}}]},"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"国家","en":"A nation is an individual country considered together with its social and political structures. →see usage note at:","ex":{"en":"Such policies would require unprecedented cooperation between nations","cn":"这样的政策要求国家间进行空前的合作。"}},{"pos":"N-SING 单数名词","cn":"全体国民;国民","en":"The nation is sometimes used to refer to all the people who live in a particular country.","ex":{"en":"It was a story that touched the nation's heart.","cn":"这是一个感动了全体国民的故事。"}}]},"examples":[{"en":"The entire nation, it seemed, was watching TV.","cn":"好像全国的人都在看电视。"},{"en":"Citizenship is about the sense of nationhood.","cn":"公民身分涉及国家意识。"}]},"natural":{"media":{"img":["media/pic/musicalnotation.jpg","media/thumb/natural.jpg"],"uk":"media/uk/natural__gb_1.mp3","us":"media/us/natural__us_1.mp3"},"oxford":{"phon":"ˈnætʃrəl","pos":"adjective","senses":[{"en":"existing in nature; not made or caused by humans","cn":"自然的；天然的","g":"[only before noun]","sc":"in nature","ex":{"en":"the natural world (= of trees, rivers, animals and birds)","cn":"自然界"}},{"en":"having little or no processing","cn":"天然的；原味的；未经加工的","sc":"in nature","ex":{"en":"natural yogurt (= with no flavour added)","cn":"原味酸奶"}},{"en":"normal; as you would expect","cn":"正常的；自然的；意料之中的","sc":"expected","ex":{"en":"to die of natural causes (= not by violence, but normally, of old age)","cn":"自然死亡"}},{"en":"used to describe behaviour or abilities that are part of the character that a person or an animal was born with","cn":"天生的；本能的；与生俱来的","sc":"behaviour/ability","ex":{"en":"the natural agility of a cat","cn":"猫天生的敏捷灵活"}},{"en":"having an ability that you were born with","cn":"天赋的；天生具有某种能力的","g":"[only before noun]","sc":"behaviour/ability","ex":{"en":"He's a natural leader.","cn":"他是个天生的领袖。"}},{"en":"relaxed and not pretending to be somebody/something different","cn":"不拘束的；不做作的；自然的","sc":"relaxed","ex":{"en":"It's difficult to look natural when you're feeling nervous.","cn":"当你紧张的时候，很难显得轻松自然。"}},{"en":"related by blood","cn":"有血缘关系的；亲生的","g":"[only before noun]","sc":"parents/children","ex":{"en":"His natural mother was unable to care for him so he was raised by an aunt.","cn":"他的生母不能照顾他，所以他是姑姑抚养大的。"}},{"en":"born to parents who are not married","cn":"非婚生的；私生的","g":"[only before noun]","lab":"old use or formal","sc":"parents/children","ex":{"en":"She was a natural daughter of King James II.","cn":"她是国王詹姆斯二世的私生女。"}},{"en":"based on human reason alone","cn":"符合人的理性的；正常的；自然的","g":"[only before noun]","sc":"based on human reason","ex":{"en":"I am a firm believer in human rights and natural law.","cn":"我坚信人权和自然法。"}},{"en":"used after the name of a note to show that the note is neither sharp nor flat. The written symbol is (♮).","cn":"本位音的，标有还原号的（书写符号为 ♮）","sc":"in music","ex":{"en":"B natural","cn":"B 本位音"}},{"en":"a person who is very good at something without having to learn how to do it, or who has all the right qualities for a particular job","cn":"有天赋的人；适合做某事的人","sc":"person","ex":{"en":"She took to flying like a natural.","cn":"她有极高的飞行天赋，一下子就会了。"},"pos":"noun"},{"en":"a normal musical note, not its sharp or flat form. The written symbol is (♮).","cn":"本位音，还原音，本位号（书写符号为 ♮）","sc":"in music","pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"自然的;正常的;合乎常情的","en":"If you say that it is natural for someone to act in a particular way or for something to happen in that way, you mean that it is reasonable in the circumstances.","ex":{"en":"It is only natural for youngsters to crave the excitement of driving a fast car","cn":"年轻人追求开快车的刺激是太正常不过的事情。"}},{"pos":"ADJ 形容词","cn":"(行为)出于本性的，生来就有的","en":"Natural behaviour is shared by all people or all animals of a particular type and has not been learned.","ex":{"en":"...the insect's natural instinct to feed","cn":"昆虫进食的本能"}},{"pos":"ADJ 形容词","cn":"(能力或技能)天赋的，天生的","en":"Someone with a natural ability or skill was born with that ability and did not have to learn it.","ex":{"en":"She has a natural ability to understand the motives of others","cn":"她有一种洞察他人动机的天赋。"}},{"pos":"N-COUNT 可数名词","cn":"天生的料子;天才","en":"If you say that someone is a natural, you mean that they do something very well and very easily.","ex":{"en":"He's a natural with any kind of engine","cn":"他天生就会摆弄各种发动机。"}},{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"轻松自如的;不局促的;不做作的","en":"If someone's behaviour is natural, they appear to be relaxed and are not trying to hide anything.","ex":{"en":"Bethan's sister was as friendly and natural as the rest of the family","cn":"贝唐的妹妹和她家的其他人一样友好、随意。"}},{"pos":"ADJ 形容词","cn":"非人为的;自然的;天然的","en":"Natural things exist or occur in nature and are not made or caused by people.","ex":{"en":"It has called the typhoon the worst natural disaster in South Korea in many years","cn":"它称这次台风为韩国多年来最严重的自然灾害。"}},{"pos":"ADJ 形容词","cn":"(父母或子女)亲生的，有血缘关系的","en":"Someone's natural parent is their biological father or mother, as opposed to an adult who is looking after them or has adopted them. Someone's natural child is their biological son or daughter, as opposed to a child they are looking after or have adopted.","ex":{"en":"She has been reunited with her natural mother","cn":"她和亲生母亲团聚了。"}},{"pos":"ADJ 形容词","cn":"(音符)本位音的，标有还原号的","en":"In music, a natural note is the ordinary note, not its sharp or flat form.","ex":{"en":"...B natural. B","cn":"本位音"}},{"pos":"PHRASE 短语","cn":"(死亡)出于自然原因","en":"If someone dies of or from natural causes, they die because they are ill or old rather than because of an accident or violence.","ex":{"en":"According to the Home Office, your brother died of natural causes","cn":"根据内政部的调查，你哥哥属正常死亡。"}}]},"examples":[{"en":"His natural mother was unable to care for him so he was raised by an aunt.","cn":"他的生母不能照顾他，所以他是姑姑抚养大的。"},{"en":"He thought social inequality was all part of the natural order of things.","cn":"他认为社会不平等完全合乎事物的自然规律。"}]},"national":{"media":{"uk":"media/uk/national__gb_1.mp3","us":"media/us/national__us_1.mp3"},"oxford":{"phon":"ˈnæʃnəl","pos":"adjective","senses":[{"en":"connected with a particular nation; shared by a whole nation","cn":"国家的；民族的；全国的","ex":{"en":"Decide whether it would be better to advertise in a national or a local newspaper.","cn":"要确定一下是在全国性还是地方性报纸上做广告更好。"}},{"en":"owned, controlled or paid for by the government","cn":"国有的；国立的；国营的","ex":{"en":"a national airline/museum/theatre","cn":"国营航空公司；国立博物馆；国家剧院"}},{"en":"a citizen of a particular country","cn":"（某国的）公民","ex":{"en":"Polish nationals living in Germany","cn":"生活在德国的波兰公民"},"pos":"noun"}]},"collins":{"senses":[{"pos":"ADJ 形容词","cn":"国家的;全国的","en":"National means relating to the whole of a country or nation rather than to part of it or to other nations.","ex":{"en":"Ruling parties have lost ground in national and local elections.","cn":"执政党在全国和地区选举中均败北。"}},{"pos":"ADJ 形容词","cn":"国民的;民族的","en":"National means typical of the people or customs of a particular country or nation.","ex":{"en":"...the national characteristics and history of the country","cn":"这个国家的民族特征和历史"}},{"pos":"N-COUNT 可数名词","cn":"国民;国人","en":"You can refer to someone who is legally a citizen of a country as a national of that country.","ex":{"en":"...a Sri-Lankan-born British national.","cn":"出生于斯里兰卡的英国国民"}}]},"examples":[{"en":"These buildings are part of our national heritage.","cn":"这些建筑是我们民族遗产的一部分。"},{"en":"They are afraid of losing their national identity.","cn":"他们担心会失去他们的民族特色。"}]},"narrowing":{"oxford":{"phon":"ˈnærəʊ","pos":"adjective","senses":[{"en":"measuring a short distance from one side to the other, especially in relation to length","cn":"狭窄的；窄小的"},{"en":"only just achieved or avoided","cn":"勉强的；刚刚好的"}]}},"named":{"oxford":{"phon":"neɪm","pos":"noun","senses":[{"en":"a word or words that a particular person, animal, place or thing is known by","cn":"名字；名称"},{"en":"a reputation that sb/sth has; the opinion that people have about sb/sth","cn":"名誉；名声；名气"}]}},"narrowed":{"oxford":{"phon":"ˈnærəʊ","pos":"adjective","senses":[{"en":"measuring a short distance from one side to the other, especially in relation to length","cn":"狭窄的；窄小的"},{"en":"only just achieved or avoided","cn":"勉强的；刚刚好的"}]}},"names":{"oxford":{"phon":"neɪm","pos":"noun","senses":[{"en":"a word or words that a particular person, animal, place or thing is known by","cn":"名字；名称"},{"en":"a reputation that sb/sth has; the opinion that people have about sb/sth","cn":"名誉；名声；名气"}]}},"narratives":{"oxford":{"phon":"ˈnærətɪv","pos":"noun","senses":[{"en":"a description of events, especially in a novel （","cn":"尤指小说中的）描述，叙述"},{"en":"the act, process or skill of telling a story","cn":"讲故事；叙述；叙事技巧"}]}},"nails":{"oxford":{"phon":"neɪl","pos":"noun","senses":[{"en":"thin hard layer covering the outer tip of the fingers or toes","cn":"指甲；趾甲"},{"en":"a small thin pointed piece of metal with a flat head, used for hanging things on a wall or for joining pieces of wood together","cn":"钉；钉子"}]},"media":{"img":["media/ldoce/img/nails.jpg"]}},"nations":{"oxford":{"phon":"ˈneɪʃn","pos":"noun","senses":[{"en":"a country considered as a group of people with the same language, culture and history, who live in a particular area under one government","cn":"国家；民族"},{"en":"all the people in a country","cn":"国民"}]}},"navigation":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"航行;航海","en":"You can refer to the movement of ships as navigation .","ex":{"en":"Pack ice around Iceland was becoming a threat to navigation.","cn":"冰岛周围的浮冰群曾一度对船只航行构成威胁。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the science or job of planning which way you need to go when you are travelling from one place to another","cn":"航行学﹔航海术﹔航空术"},{"en":"when someone sails a ship along a river or other area of water 〔","cn":"水上的〕航行"},{"en":"when you click on words, pictures etc in order to move between documents that are connected on the Internet 〔","cn":"因特网上的〕浏览"}]},"vocab":{"pos":"n","senses":[{"en":"Navigation is all about figuring out how to get somewhere. If you are lost, hopefully your cell phone can act as a navigation device."}]},"collocations":{"phrases":["ADJ. accurate | radio, satellite","NAVIGATION + NOUN system | aids, equipment, instruments, lights | beacon | rights","PREP. ~ through (often figurative) navigation through complex documents","PHRASES an aid to navigation small boats equipped with electronic aids to navigation | freedom/rights of navigation freedom of navigation th"]},"media":{"uk":"media/ldoce/hwd/bre/f/navigation0205.mp3","us":"media/ldoce/hwd/ame/5/ld41navigation.mp3"},"examples":[{"en":"the right of navigation through international waters","cn":"通过国际水域的航行权"},{"en":"navigation systems","cn":"导航系统"}],"oxford":{"phon":"ˌnævɪˈɡeɪʃn","pos":"noun","senses":[{"en":"the skill or the process of planning a route for a ship or other vehicle and taking it there","cn":"导航；领航","ex":{"en":"a maker of in-car navigation systems","cn":"车内导航系统的生产商"}},{"en":"the movement of ships or aircraft","cn":"航行","ex":{"en":"the right of navigation through international waters","cn":"通过国际水域的航行权"}},{"en":"the way that you move around a website or the internet when you are looking for information","cn":"（网站或互联网的）导航","ex":{"en":"The site was redesigned to improve navigation.","cn":"该网站为改进导航重新进行了设计。"}}]}},"nausea":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"恶心;呕吐感","en":"Nausea is the condition of feeling sick and the feeling that you are going to vomit.","ex":{"en":"I was overcome with a feeling of nausea.","cn":"我觉得想吐。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"pain in your stomach or near your stomach","cn":""},{"en":"pain or uncomfortable feelings that you get when your stomach cannot break down food that you have eaten","cn":""},{"en":"a stomach illness caused by eating food that contains harmful bacteria, so that you vomit","cn":""}]},"vocab":{"pos":"n","senses":[{"en":"When you feel like you might throw up, that's nausea . I know you're feeling sea sick, but if our boat sinks, nausea will be the least of your problems."}]},"collocations":{"phrases":["ADJ. intense, severe | sudden | nervous","QUANT. wave I was overcome by waves of nausea.","VERB + NAUSEA experience, feel | complain of | bring on, cause | relieve","NAUSEA + VERB engulf sb, overcome sb, sweep over sb","PHRASES a feeling/sensation of nausea"]},"media":{"uk":"media/ldoce/hwd/bre/7/nausea0205.mp3","us":"media/ldoce/hwd/ame/f/ld41nausea.mp3"},"examples":[{"en":"Nausea and vomiting are common symptoms.","cn":"恶心呕吐是常见的症状。"},{"en":"A wave of nausea swept over her.","cn":"她觉得一阵恶心。"}],"oxford":{"phon":"ˈnɔːziə","pos":"noun","senses":[{"en":"the feeling that you have when you want to vomit, for example because you are sick or are shocked or frightened by something","cn":"恶心；作呕；反胃","ex":{"en":"A wave of nausea swept over her.","cn":"她觉得一阵恶心。"}}]}},"nap":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"(尤指在白天的)打盹，小睡","en":"If you have a nap, you have a short sleep, usually during the day.","ex":{"en":"Use your lunch hour to have a nap in your chair","cn":"利用午饭时间坐在椅子上打个盹吧。"}},{"pos":"VERB 动词","cn":"(尤指在白天)小睡，打盹","en":"If you nap, you sleep for a short period of time, usually during the day.","ex":{"en":"An elderly person may nap during the day and then sleep only five hours a night.","cn":"老年人白天会小睡一会儿，然后晚上只睡5个小时。"}},{"pos":"N-SING 单数名词","cn":"(地毯或天鹅绒等表面的)绒毛","en":"The nap of a carpet or of a cloth such as velvet is the top layer of short threads, which usually lie smoothly in one direction."},{"pos":"PHRASE 短语","cn":"被弄得措手不及;猝不及防","en":"If someone is caught napping, something happens when they are not prepared for it, although they should have been.","ex":{"en":"The security services were clearly caught napping.","cn":"保安工作明显有漏洞。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the natural state of resting your mind and body, when your eyes are closed and you do not notice anything happening around you","cn":""},{"en":"sleep","cn":""},{"en":"sleep","cn":""}]},"collocations":{"phrases":["ADJ. brief, little, quick, short | afternoon, morning | cat (also catnap) If you have difficulty sleeping at night, avoid taking catnaps dur","VERB + NAP have, take I had a short nap after lunch."]},"media":{"uk":"media/ldoce/hwd/bre/9/nap_n0205.mp3","us":"media/ldoce/hwd/ame/5/ld41nap.mp3"},"examples":[{"en":"to take/have a nap","cn":"打个盹"},{"en":"I usually take a nap after lunch.","cn":"我午饭后通常要小睡一会儿。"}],"oxford":{"phon":"næp","pos":"noun","senses":[{"en":"a short sleep, especially during the day","cn":"（日间的）小睡，打盹","g":"[countable]","ex":{"en":"to take/have a nap","cn":"打个盹；小睡一会儿"}},{"en":"the short fine threads on the surface of some types of cloth, usually lying in the same direction","cn":"（某些织物表面的）短绒毛","g":"[singular]"},{"en":"advice given by an expert on which horse is most likely to win a race","cn":"赛马情报；赛马结果预测","g":"[countable]","lab":"British English"},{"en":"to sleep for a short time, especially during the day","cn":"打盹，小睡（尤指日间）","ex":{"en":"I tried to nap on the plane.","cn":"我想在飞机上打个盹。"},"pos":"verb"}]}},"nationalism":{"collins":{"senses":[{"pos":"N-UNCOUNT 不可数名词","cn":"国家主义;民族独立主义","en":"Nationalism is the desire for political independence of people who feel they are historically or culturally a separate group within a country.","ex":{"en":"...the rising tide of Slovak nationalism.","cn":"不断高涨的斯洛伐克民族独立主义浪潮"}},{"pos":"N-UNCOUNT 不可数名词","cn":"民族主义;民族优越感","en":"You can refer to a person's great love for their nation as nationalism. It is often associated with the belief that a particular nation is better than any other nation, and in this case is often used showing disapproval.","ex":{"en":"This kind of fierce nationalism is a powerful and potentially volatile force.","cn":"这种强烈的民族主义情绪是一股强大的、可能会突然爆发的潜在力量。"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the desire by a group of people of the same race, origin, language etc to form an independent country","cn":"国家主义﹔民族主义"},{"en":"love for your own country and the belief that it is better than any other country","cn":"本国优越感﹔民族自豪感"}]},"vocab":{"pos":"n","senses":[{"en":"Nationalism is the belief that your own country is better than all others. Sometimes nationalism makes people not want to work with other countries to solve shared problems."}]},"collocations":{"phrases":["ADJ. aggressive, extreme, fierce, militant, revolutionary | popular | conservative, radical | secular | black | cultural, economic, politica","PHRASES the growth of nationalism, the resurgence/revival of nationalism, the rise in nationalism, a tide of nationalism a tide of militant "]},"media":{"uk":"media/ldoce/hwd/bre/e/nationalism0205.mp3","us":"media/ldoce/hwd/ame/0/ld41nationalism.mp3"},"examples":[{"en":"Scottish nationalism","cn":"苏格兰国家主义"},{"en":"Under his leadership, a strong sense of nationalism emerged.","cn":"在他的领导下﹐人们心中涌出强烈的民族自豪感。"}],"oxford":{"phon":"ˈnæʃnəlɪzəm","pos":"noun","senses":[{"en":"the desire by a group of people who share the same ethnic group, culture, language, etc. to form an independent country","cn":"国家主义","ex":{"en":"Scottish nationalism","cn":"苏格兰国家主义"}},{"en":"a feeling of loving your country very much and being very proud of it; a feeling that your country is better than any other","cn":"民族主义；民族自豪感；民族优越感","lab":"sometimes disapproving","ex":{"en":"The war was fuelled by aggressive nationalism and feelings of cultural superiority.","cn":"这场战争因激进的民族主义和文化优越感而进一步激发。"}}]}},"nationalistic":{"collins":{"senses":[{"pos":"ADJ-GRADED 能被表示程度的副词或介词词组修饰的形容词","cn":"民族主义的;怀有民族自豪感的;怀有民族优越感的","en":"If you describe someone as nationalistic, you mean they are very proud of their nation. They also often believe that their nation is better than any other nation, and in this case it is often used showing disapproval.","ex":{"en":"...the nationalistic pride of the Catalan people.","cn":"加泰罗尼亚人的民族自豪感"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"someone who is nationalistic is very proud of their own country, but often has no respect for people from other countries because they believe that their own country is much better","cn":""},{"en":"someone who is nationalistic believes that their country is better than other countries","cn":"有民族优越感的，爱国的"}]},"collocations":{"phrases":["VERBS be | become | remain","ADV. fiercely, intensely, strongly | increasingly"]},"media":{"uk":"media/ldoce/hwd/bre/1/nationalistic0205.mp3","us":"media/ldoce/hwd/ame/b/ld41nationalistic.mp3"},"examples":[{"en":"They were encouraging nationalistic sentiment among the students.","cn":"他们在鼓动学生们的爱国情绪。"}],"oxford":{"phon":"ˌnæʃnəˈlɪstɪk","pos":"adjective","senses":[{"en":"loving your country very much and being very proud of it, so that you think that it is better than any other","cn":"民族主义的"}]}},"nationality":{"collins":{"senses":[{"pos":"N-VAR 可变名词","cn":"国籍","en":"If you have the nationality of a particular country, you were born there or have the legal right to be a citizen.","ex":{"en":"Asked his nationality, he said British","cn":"被问及国籍时，他说是英国。"}},{"pos":"N-COUNT 可数名词","cn":"(尤指未建立独立国家的)民族","en":"You can refer to people who have the same racial origins as a nationality, especially when they do not have their own independent country.","ex":{"en":"...the many nationalities that comprise Ethiopia.","cn":"组成埃塞俄比亚的众多民族"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"the legal right to live in a country, use this especially when this right is given to someone who comes from another country","cn":""},{"en":"the state of being legally a citizen of a particular country","cn":"国籍"},{"en":"a large group of people with the same race, origin, language etc","cn":"民族"}]},"vocab":{"pos":"n","senses":[{"en":"Your nationality is the country you come from: American, Canadian, and Russian are all nationalities ."}]},"collocations":{"phrases":["ADJ. various cultural differences among various nationalities | mixed teams of mixed nationality | dual He has dual British and South Africa","VERB + NATIONALITY have | acquire, adopt, assume, obtain, take She is hoping to adopt Australian nationality. | inherit | retain | change | ","NATIONALITY + VERB be represented About 30 nationalities were represented at the tournament.","PHRASES on (the) grounds of nationality He accused them of discrimination on the grounds of nationality."]},"media":{"uk":"media/ldoce/hwd/bre/f/nationality0205.mp3","us":"media/ldoce/hwd/ame/5/ld41nationality.mp3"},"examples":[{"en":"All applicants will be considered regardless of age, sex, religion or nationality.","cn":"所有申请者，不论其年龄、性别、宗教信仰及国籍，都可考虑。"},{"en":"Kazakhstan alone contains more than a hundred nationalities.","cn":"单是哈萨克斯坦就有一百多个民族。"}],"oxford":{"phon":"ˌnæʃəˈnæləti","pos":"noun","senses":[{"en":"the legal status of belonging to a particular nation","cn":"国籍","g":"[uncountable, countable]","ex":{"en":"to take/have/hold French nationality","cn":"获得／拥有／持有法国国籍"}},{"en":"a group of people with the same language, culture and history who form part of a political nation","cn":"（构成国家一部分的）民族","g":"[countable]","ex":{"en":"Kazakhstan alone contains more than a hundred nationalities.","cn":"单是哈萨克斯坦就有一百多个民族。"}}]}},"narcotic":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"致幻毒品;麻醉品;(泛指)毒品(亦写作narcotics，尤用于美国英语中)","en":"Narcotics are drugs such as opium or heroin which make you sleepy and stop you feeling pain. You can also use narcotics, especially in American English, to mean any kind of illegal drug.","ex":{"en":"He was indicted for dealing in narcotics","cn":"他因从事毒品交易被起诉。"}},{"pos":"ADJ 形容词","cn":"(尤指药物)麻醉的，致幻的，催眠的","en":"If something, especially a drug, has a narcotic effect, it makes the person who uses it feel sleepy.","ex":{"en":"...hormones that have a narcotic effect on the immune system.","cn":"对免疫系统有麻醉作用的激素"}}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"an illegal substance that people take for pleasure, or because they cannot stop taking it","cn":""},{"en":"illegal drugs - used especially in news reports and in legal contexts","cn":""},{"en":"an illegal drug of any type - used especially in legal and official contexts","cn":""}]},"vocab":{"pos":"n adj","senses":[{"en":"Use the noun narcotic to talk about a pain relieving or sleep inducing drug and the adjective narcotic to describe anything that has these same effects."}]},"collocations":{"phrases":["ADJ. mild, powerful","VERB + NARCOTIC inject, use | trade in He has been arrested for trading in narcotics.","NARCOTIC + NOUN agent, officer, official, squad • Note at DRUG (for more verbs and nouns)"]},"media":{"uk":"media/ldoce/hwd/bre/7/narcotic_n0205.mp3","us":"media/ldoce/hwd/ame/6/ld41narcotic2.mp3"},"examples":[{"en":"a narcotics agent (= a police officer investigating the illegal trade in drugs)","cn":"缉毒警察"},{"en":"a mild narcotic","cn":"药性温和的镇静剂"}],"oxford":{"phon":"nɑːˈkɒtɪk","pos":"noun","senses":[{"en":"a powerful illegal drug that affects the mind in a harmful way. Heroin and cocaine are narcotics.","cn":"致幻毒品；麻醉品","lab":"formal","ex":{"en":"a narcotics agent (= a police officer investigating the illegal trade in drugs)","cn":"缉毒警察"}},{"en":"a substance that relaxes you, reduces pain or makes you sleep","cn":"麻醉性镇痛药；麻醉药；镇静剂","lab":"medical","ex":{"en":"a mild narcotic","cn":"药性温和的镇静剂"}},{"en":"that affects your mind in a harmful way","cn":"致幻的；麻醉的","pos":"adjective"},{"en":"making you sleep","cn":"催眠的","ex":{"en":"a mild narcotic effect","cn":"温和的催眠作用"},"pos":"adjective"}]}},"nationalist":{"collins":{"senses":[{"pos":"ADJ 形容词","cn":"民族独立主义的;国家主义的","en":"Nationalist means connected with the desire of a group of people within a country for political independence.","ex":{"en":"The crisis has set off a wave of nationalist feelings in Quebec.","cn":"这一危机已在魁北克激起了一波民族独立主义情绪。"}},{"pos":"ADJ 形容词","cn":"民族主义的;怀有民族优越感的","en":"Nationalist means connected with a person's great love for their nation. It is often associated with the belief that their nation is better than any other nation, and in this case is often used showing disapproval.","ex":{"en":"Political life has been infected by growing nationalist sentiment.","cn":"政治生活已受到了不断高涨的民族主义情绪的影响。"}}]},"ldoce":{"phon":"hwd","pos":"adjective","senses":[{"en":"a nationalist organization, party etc wants to gain or keep political independence for their country and people","cn":"国家主义的﹔民族主义的"},{"en":"a nationalist organization or party believes that their country is the most important or the best 〔","cn":"组织或党派〕怀有极度民族优越感的"},{"en":"someone who is involved in trying to gain or keep political independence for their country and people","cn":"国家主义者﹔民族主义者"}]},"vocab":{"pos":"n adj","senses":[{"en":"A nationalist is a person who favors independence for a country. A Scottish nationalist , for example, believes that Scotland should be independent and separate from Great Britain."}]},"collocations":{"phrases":["ADJ. ardent | extreme, hard-line, radical | militant | moderate | left-wing, liberal | conservative, right-wing | veteran | former | local |","NATIONALIST + NOUN leader | forces, troops | uprising leading a nationalist uprising"]},"media":{"uk":"media/ldoce/hwd/bre/6/nationalist_ad0205.mp3","us":"media/ldoce/hwd/ame/9/ld41nationalist.mp3"},"examples":[{"en":"Scottish nationalists","cn":"苏格兰国家主义者"},{"en":"nationalist sentiments","cn":"民族主义感情"}],"oxford":{"phon":"ˈnæʃnəlɪst","pos":"adjective","senses":[{"en":"wanting your country to become independent","cn":"希望你的国家独立","ex":{"en":"the nationalist movement/party","cn":"民族主义运动/政党"}},{"en":"loving your country very much and being very proud of it; feeling that your country is better than any other","cn":"民族主义者；怀有本民族优越感者","lab":"sometimes disapproving","ex":{"en":"nationalist sentiments","cn":"民族主义情绪"}},{"en":"a person who wants their country to become independent","cn":"国家主义者","ex":{"en":"Scottish nationalists","cn":"苏格兰国家主义者"},"pos":"noun"},{"en":"a person who loves their country very much and is very proud of it; a person who feels that their country is better than any other","cn":"民族主义者","lab":"sometimes disapproving","pos":"noun"}]}},"nappy":{"collins":{"senses":[{"pos":"N-COUNT 可数名词","cn":"尿布","en":"A nappy is a piece of soft thick cloth or paper which is fastened round a baby's bottom in order to soak up its urine and faeces."}]},"ldoce":{"phon":"hwd","pos":"noun","senses":[{"en":"a piece of soft cloth or paper worn by a baby between its legs and fastened around its waist to hold its liquid and solid waste","cn":"尿布"},{"en":"SYN diaper American English : Excuse me while I change the baby’s nappy .","cn":"对不起﹐我给宝宝换一下尿布。 a dirty nappy 脏尿布 disposable nappies 一次性尿布 (= nappies which are made to be used once and thrown away ) na"}]},"collocations":{"phrases":["ADJ. clean | wet | dirty, soiled | disposable | washable | cloth, terry","VERB + NAPPY have on, wear | change | put on | remove, take off | wash | dispose of","NAPPY + NOUN change, changing | liner | pin | rash","PREP. in ~ Isn't he rather old to be still in nappies? •"]},"media":{"uk":"media/ldoce/hwd/bre/5/nappy0205.mp3","us":"media/ldoce/hwd/ame/9/ld41nappy.mp3"},"examples":[{"en":"I'll change her nappy.","cn":"我要给她换尿布。"},{"en":"a disposable nappy (= one that is made to be used once only)","cn":"一次性尿布"}],"oxford":{"phon":"ˈnæpi","pos":"noun","senses":[{"en":"a piece of soft cloth or other thick material that is folded around a baby’s bottom and between its legs to take in and hold its body waste","cn":"尿布","lab":"especially US English","ex":{"en":"I'll change her nappy.","cn":"我来给她换尿布吧。"}}]}}});
